import Link from "next/link";
import { BadgePercent, Coins, FolderLock, Info, Map as MapIcon, Search, ShieldCheck } from "lucide-react";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Button from "@/components/ui/Button";
import Reveal from "@/components/ui/Reveal";
import BoerseListe from "@/components/Boerse/BoerseListe";
import Hero from "@/components/Boerse/Seite/Hero";
import Marktbild from "@/components/Boerse/Seite/Marktbild";
import Ablauf from "@/components/Boerse/Seite/Ablauf";
import { abs, SITE, sprachAlternates } from "@/data/site";
import { PROVISION, PHASEN } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";
import { backend, istDemo } from "@/lib/plattform/backend";
import { PlattformFehler } from "@/lib/plattform/fehler";

export const dynamic = "force-dynamic";

const PFAD = "/projektboerse";
const TITEL = "PV-Projektbörse DACH: Solarparks & Projektrechte | ÖkoInvest";
const BESCHREIBUNG =
  "Solarparks, Agri-PV, Parkplatz-PV und Großspeicher im DACH-Raum: geprüfte Projekte in allen Phasen, NDA per Klick, Datenraum – für Investoren kostenfrei.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: sprachAlternates("/projektboerse", "/en/project-exchange"),
  openGraph: {
    type: "website",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/solarpark-reihen.jpg"), width: 1280, height: 852, alt: "Reihen eines Solarparks" }],
  },
};

const SPANNE = `${fmt(PROVISION.verkaeufer.min * 100, 1)}–${fmt(PROVISION.verkaeufer.max * 100, 0)} %`;

const ERLAUBTE_FILTER = ["typ", "land", "phase", "mwpMin", "mwpMax", "sortierung"];

const FAQ = [
  {
    q: "Was kostet die Projektbörse?",
    a: `Für Investoren ist die Börse ${PROVISION.kaeufer.text.replace("für Investoren ", "")}. Anbieter zahlen eine Erfolgsprovision von ${PROVISION.verkaeufer.text} – keine Einstell- oder Listungsgebühren.`,
  },
  {
    q: "Warum sehe ich keine genaue Lage?",
    a: "Öffentlich zeigen wir nur Region, Bundesland bzw. Kanton und Eckdaten. Gemeinde, Flurstücke, Netzbetreiber und Unterlagen sehen registrierte Investoren erst, nachdem sie die Vertraulichkeitsvereinbarung akzeptiert haben und das Backoffice den Datenraum freigegeben hat. Das schützt Flächeneigentümer und Anbieter.",
  },
  {
    q: "Wie werden Projekte geprüft?",
    a: "Vor der Veröffentlichung prüft das Backoffice Angaben und Kernunterlagen auf Vollständigkeit und Plausibilität – etwa Flächensicherung, Stand der Bauleitplanung und Netzanschluss. Eine rechtliche und technische Due Diligence ersetzt das nicht; sie bleibt Aufgabe des Käufers.",
  },
  {
    q: "Welche Phasen gibt es?",
    a: `Wir unterscheiden ${PHASEN.length} Entwicklungsstände – von „${PHASEN[0].label}“ bis „${PHASEN[PHASEN.length - 1].label}“. Je weiter ein Projekt entwickelt ist, desto geringer das Risiko und desto höher der Preis je kWp.`,
  },
];

export default async function Projektboerse({ searchParams }) {
  const sp = await searchParams;
  const start = Object.fromEntries(ERLAUBTE_FILTER.map((k) => [k, typeof sp?.[k] === "string" ? sp[k].slice(0, 20) : ""]).filter(([, v]) => v));

  let daten = null;
  let fehler = "";
  try {
    daten = await backend().boerse(null, {});
  } catch (e) {
    fehler = e instanceof PlattformFehler ? e.message : "Die Projektbörse ist vorübergehend nicht erreichbar.";
    if (!(e instanceof PlattformFehler)) console.error("[projektboerse]", e);
  }
  const demo = istDemo();
  const kz = daten?.kennzahlen;

  const jsonLd = daten && {
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    name: "Projektbörse ÖkoInvest",
    url: abs(PFAD),
    description: BESCHREIBUNG,
    publisher: { "@type": "Organization", name: SITE.firma, url: SITE.url },
    mainEntity: {
      "@type": "ItemList",
      numberOfItems: daten.projekte.length,
      itemListElement: daten.projekte.map((p, i) => ({ "@type": "ListItem", position: i + 1, url: abs(`${PFAD}/${p.slug}`), name: p.titel })),
    },
  };

  return (
    <>
      {jsonLd && <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }} />}
      <Hero
        breadcrumbs={[{ name: "Projektbörse", href: PFAD }]}
        pill={kz ? { marke: "Live", text: `${kz.anzahl} ${kz.anzahl === 1 ? "Projekt" : "Projekte"} aus DACH – jetzt durchsuchen`, href: "#projekte" } : { marke: "DACH", text: "Projektbörse für Solar und Speicher", href: "#projekte" }}
        titel={<>Die Projektbörse für Solarprojekte&nbsp;– <span className="ov-text-gradient-light">geprüft und vertraulich.</span></>}
        lead={<><span className="font-medium text-white">Freiflächen-PV, Agri-PV, Parkplatz-PV und Großspeicher</span> in Deutschland, Österreich und der Schweiz – von der Flächensicherung bis zur Bestandsanlage. Öffentlich als anonymer Teaser, Details erst nach NDA.</>}
        aktionen={[
          { label: "Als Investor registrieren", href: "/registrieren?rolle=investor" },
          { label: "Projekt anbieten", href: "/projektboerse/anbieten" },
        ]}
        hinweis={`Für Investoren kostenfrei · Anbieter zahlen ${SPANNE} Provision, nur bei Abschluss`}
        unten={
          <p className="mt-6 flex items-center gap-2 text-[14px] text-white/70">
            <MapIcon aria-hidden="true" className="h-4 w-4 shrink-0 text-sun-300" />
            <span>Lieber nach Region suchen? <Link href="/projektboerse/karte" className="rounded font-semibold text-white underline decoration-sun-300/70 underline-offset-4 transition-colors hover:decoration-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300">Zur Kartenansicht</Link></span>
          </p>
        }
      />
      {daten && <Marktbild projekte={daten.projekte} kennzahlen={kz} />}

      <section id="projekte" aria-labelledby="projekte-titel" className="scroll-mt-20 bg-sand-50 pb-20 pt-16 md:pb-28 md:pt-24">
        <div className="ov-container">
          <SectionHeading className="mb-8 md:mb-10" eyebrow="Aktuelle Projekte" title={<span id="projekte-titel">Projekte in allen Phasen</span>} lead="Filtern Sie nach Typ, Land, Phase und Leistung – oder wechseln Sie zur Karte. Ihre Auswahl steht in der Adresse und lässt sich teilen." />
          {demo && (
            <p className="mb-6 flex items-start gap-3 rounded-2xl bg-sun-300/25 px-5 py-4 text-[14.5px] leading-relaxed text-ink-900 ring-1 ring-inset ring-sun-400/50">
              <Info aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ink-700" />
              <span><strong>Vorführdaten:</strong> Die Plattform läuft im Demo-Modus. Alle gezeigten Projekte sind fiktive Beispiele und keine Angebote.</span>
            </p>
          )}
          {fehler ? (
            <div className="rounded-3xl bg-white p-8 text-center ring-1 ring-ink-200/70">
              <p className="font-display text-[20px] font-bold text-ink-900">Projektbörse derzeit nicht verfügbar</p>
              <p className="mt-2 text-[15px] text-ink-600">{fehler}</p>
            </div>
          ) : (
            <BoerseListe projekte={daten.projekte} basisHref={`${PFAD}/`} start={start} />
          )}
        </div>
      </section>

      <Ablauf />

      <Section tone="ink" space="lg">
        <SectionHeading eyebrow="Zwei Seiten, ein Marktplatz" title="Fair für Käufer und Verkäufer" align="center" className="mx-auto mb-12 max-w-2xl md:mb-16" />
        <div className="grid gap-5 lg:grid-cols-2">
          <Reveal className="flex flex-col rounded-[2rem] bg-white p-7 shadow-e1 ring-1 ring-ink-200/70 md:p-10">
            <div className="flex items-start justify-between gap-4">
              <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-ov-50 text-ov-600"><ShieldCheck aria-hidden="true" className="h-6 w-6" /></span>
              <p className="text-right"><span className="ov-num block font-display text-[40px] font-extrabold leading-none tracking-tight text-ink-900 md:text-[48px]">0&nbsp;€</span><span className="mt-1 block text-[12.5px] text-ink-500">für Investoren</span></p>
            </div>
            <h3 className="ov-h3 mt-6 text-ink-900">Für Investoren: kostenfrei</h3>
            <p className="mt-3 text-[16px] leading-relaxed text-ink-600">Suchprofil, Merkliste, NDA und Datenraum sind für Investoren kostenfrei. Sie sehen Projekte aus der Entwicklung der ÖKOVOLT Gruppe und von weiteren Entwicklern.</p>
            <ul className="mt-6 grid gap-2.5 text-[15px] text-ink-700 sm:grid-cols-2">
              <li className="flex gap-2.5"><FolderLock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" /> Datenraum mit Download-Protokoll</li>
              <li className="flex gap-2.5"><Search aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" /> Matching nach Suchprofil</li>
            </ul>
            <div className="mt-auto pt-8"><Button href="/registrieren?rolle=investor" pfeil>Investorenkonto anlegen</Button></div>
          </Reveal>
          <Reveal delay={100} className="ov-noise relative flex flex-col overflow-hidden rounded-[2rem] bg-navy-950 p-7 text-white md:p-10">
            <div aria-hidden="true" className="absolute -right-20 -top-20 h-64 w-64 rounded-full bg-ov-500/30 blur-[90px]" />
            <div className="relative flex items-start justify-between gap-4">
              <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/10 text-ov-300"><BadgePercent aria-hidden="true" className="h-6 w-6" /></span>
              <p className="text-right"><span className="ov-num block font-display text-[40px] font-extrabold leading-none tracking-tight text-white md:text-[48px]">{SPANNE}</span><span className="mt-1 block text-[12.5px] text-white/60">nur bei Abschluss</span></p>
            </div>
            <h3 className="ov-h3 relative mt-6 text-white">Für Projektentwickler: Provision nur bei Erfolg</h3>
            <p className="relative mt-3 text-[16px] leading-relaxed text-white/70">Einstellen, prüfen lassen, vertraulich vermarkten. Die Provision beträgt {PROVISION.verkaeufer.text} – keine Listungsgebühren.</p>
            <ul className="relative mt-6 grid gap-2.5 text-[15px] text-white/80 sm:grid-cols-2">
              <li className="flex gap-2.5"><Coins aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-300" /> Transparente Statistik: Aufrufe, Merker, NDA-Anfragen</li>
              <li className="flex gap-2.5"><ShieldCheck aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-300" /> Anonymer Teaser, Datenraum nur nach NDA</li>
            </ul>
            <div className="relative mt-auto pt-8"><Button href="/projektboerse/anbieten" variant="white" pfeil>Projekt anbieten</Button></div>
          </Reveal>
        </div>
      </Section>

      <Section tone="white" space="lg">
        <div className="grid gap-10 lg:grid-cols-[1fr_1.4fr] lg:gap-16">
          <div>
            <SectionHeading eyebrow="Häufige Fragen" title="Projektbörse: das Wichtigste in Kürze" />
            <p className="mt-6 max-w-sm text-[15px] leading-relaxed text-ink-600">Sie möchten ein Projekt vermarkten? <Link href="/projektboerse/anbieten" className="font-semibold text-ov-700 underline decoration-ov-300 underline-offset-4 hover:text-ov-800">So funktioniert das Anbieten</Link></p>
          </div>
          <Faq items={FAQ} />
        </div>
      </Section>

      <CtaBand
        eyebrow="Projektbörse"
        title="Das passende Projekt nicht dabei?"
        text="Legen Sie ein Suchprofil an. Neue Projekte, die zu Ihren Kriterien passen, sehen Sie im Portal zuerst."
        primary={{ label: "Suchprofil anlegen", href: "/registrieren?rolle=investor" }}
        secondary={{ label: "Für Investoren", href: "/investoren" }}
      />
    </>
  );
}
import { notFound } from "next/navigation";
import { CalendarClock, Check, Coins, FileDown, Gauge, MapPin, ShieldCheck, Zap } from "lucide-react";
import Breadcrumbs from "@/components/ui/Breadcrumbs";
import Section from "@/components/ui/Section";
import Button from "@/components/ui/Button";
import CtaBand from "@/components/ui/CtaBand";
import TypIllustration, { varianteAus } from "@/components/Boerse/TypIllustration";
import Vertraulich from "@/components/Boerse/Expose/Vertraulich";
import PhasenEinordnung from "@/components/Boerse/Expose/PhasenEinordnung";
import { PhaseBadge } from "@/components/Boerse/ProjektKarte";
import { abs, SITE } from "@/data/site";
import { phaseById } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";
import { backend } from "@/lib/plattform/backend";
import { aktuellerNutzer } from "@/lib/plattform/server/seite";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { LAENDER, NETZANSCHLUSS, PROJEKT_TYPEN } from "@/lib/plattform/konstanten";
import { mwp, preisGesamt, preisText } from "@/lib/plattform/format";
import { statusLabel } from "@/lib/plattform/prozesse";

export const dynamic = "force-dynamic";

async function holen(slug, nutzer, zaehlen) {
  try {
    return await backend().boerseDetail(nutzer, slug, { zaehlen });
  } catch (e) {
    if (e instanceof PlattformFehler && [403, 404].includes(e.status)) return null;
    throw e;
  }
}

export async function generateMetadata({ params }) {
  const { slug } = await params;
  const d = await holen(slug, null, false).catch(() => null);
  if (!d) return { title: "Projekt nicht gefunden | ÖkoInvest", robots: { index: false } };
  const p = d.projekt;
  const pfad = `/projektboerse/${p.slug}`;
  const titel = `${p.titel}`.length > 46 ? `${p.titel.slice(0, 45)}… | ÖkoInvest` : `${p.titel} | ÖkoInvest`;
  const beschreibung = `${PROJEKT_TYPEN[p.typ]} mit ${mwp(p.mwp)} in ${p.region} (${LAENDER[p.land]}), Phase: ${phaseById(p.phase).label}. Exposé ansehen, NDA per Klick, Datenraum im Portal.`.slice(0, 160);
  return {
    title: titel,
    description: beschreibung,
    alternates: { canonical: abs(pfad) },
    robots: p.demo ? { index: false, follow: true } : { index: true, follow: true },
    openGraph: { type: "website", url: abs(pfad), siteName: "ÖkoInvest", title: titel, description: beschreibung, images: [{ url: abs("/img/solarpark-himmel.jpg"), width: 1280, height: 852, alt: "Solarpark unter blauem Himmel" }] },
  };
}

export default async function Expose({ params }) {
  const { slug } = await params;
  const nutzer = await aktuellerNutzer().catch(() => null);
  const d = await holen(slug, nutzer, true);
  if (!d) notFound();
  const p = d.projekt;
  const phase = phaseById(p.phase);
  const investor = nutzer?.rollen?.includes("investor");
  const portalLink = `/portal/boerse/${p.id}`;
  const freigegeben = d.zugriff !== "oeffentlich";
  const gesamt = preisGesamt(p);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Product",
    name: p.titel,
    description: p.beschreibung,
    category: PROJEKT_TYPEN[p.typ],
    url: abs(`/projektboerse/${p.slug}`),
    brand: { "@type": "Organization", name: SITE.name },
    additionalProperty: [
      { "@type": "PropertyValue", name: "Leistung", value: p.mwp, unitText: p.typ === "speicher" ? "MW" : "MWp" },
      { "@type": "PropertyValue", name: "Entwicklungsphase", value: phase.label },
      { "@type": "PropertyValue", name: "Land", value: LAENDER[p.land] },
      { "@type": "PropertyValue", name: "Region", value: p.region },
    ],
    ...(gesamt ? { offers: { "@type": "Offer", price: Math.round(gesamt), priceCurrency: "EUR", availability: p.status === "reserviert" ? "https://schema.org/LimitedAvailability" : "https://schema.org/InStock", seller: { "@type": "Organization", name: SITE.firma } } } : {}),
  };

  const eckdaten = [
    { icon: Gauge, label: "Leistung", wert: p.typ === "speicher" ? `${fmt(p.mwp, 1)} MW${p.mwhSpeicher ? ` / ${fmt(p.mwhSpeicher)} MWh` : ""}` : `${mwp(p.mwp)}${p.mwhSpeicher ? ` + ${fmt(p.mwhSpeicher)} MWh` : ""}` },
    { icon: ShieldCheck, label: "Phase", wert: phase.label },
    { icon: Zap, label: "Netzanschluss", wert: NETZANSCHLUSS[p.netzanschluss] },
    { icon: CalendarClock, label: "Inbetriebnahme geplant", wert: p.codGeplant || "offen" },
    { icon: Coins, label: "Preisindikation", wert: preisText(p) },
    { icon: MapPin, label: "Lage (grob)", wert: [p.region, p.bundesland, LAENDER[p.land]].filter(Boolean).join(", ") },
  ];

  const leistungGross = p.typ === "speicher" ? `${fmt(p.mwp, p.mwp < 10 ? 1 : 0)} MW` : mwp(p.mwp);
  const leistungZusatz = p.mwhSpeicher ? `${p.typ === "speicher" ? "/" : "+"} ${fmt(p.mwhSpeicher)} MWh Speicher` : null;
  const hauptAktion = freigegeben || investor
    ? { href: portalLink, label: freigegeben ? "Zum Datenraum im Portal" : "Im Portal öffnen & NDA anfragen" }
    : { href: `/registrieren?rolle=investor&weiter=${encodeURIComponent(portalLink)}`, label: "Als Investor anmelden & NDA anfragen" };
  const schritt = freigegeben ? 3 : investor ? 1 : 0;

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }} />
      <section aria-labelledby="expose-titel" className="relative isolate overflow-hidden bg-sand-50">
        <div aria-hidden="true" className="ov-grid-bg-light pointer-events-none absolute inset-0 -z-10" />
        <div aria-hidden="true" className="pointer-events-none absolute -right-40 -top-40 -z-10 h-[520px] w-[520px] rounded-full bg-ov-200/40 blur-[120px]" />
        <div className="ov-container relative pb-16 pt-6 sm:pt-8 md:pb-24 md:pt-10">
          <Breadcrumbs items={[{ name: "Projektbörse", href: "/projektboerse" }, { name: p.titel }]} className="ov-hero-in mb-8 md:mb-12" />
          <div className="grid items-start gap-10 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)] lg:gap-14">
            <div className="min-w-0">
              <div className="ov-hero-in flex flex-wrap items-center gap-2" style={{ "--ov-delay": "40ms" }}>
                <PhaseBadge phase={p.phase} />
                <span className="rounded-full bg-white px-2.5 py-1 text-[12px] font-semibold text-ink-700 ring-1 ring-ink-200/70">{PROJEKT_TYPEN[p.typ]}</span>
                {p.status === "reserviert" && <span className="rounded-full bg-navy-900 px-2.5 py-1 text-[12px] font-semibold text-white">{statusLabel("projekt", "reserviert")}</span>}
                {p.demo && <span className="rounded-full bg-sun-400 px-2.5 py-1 text-[11.5px] font-bold uppercase tracking-wide text-navy-950">Demo-Projekt · fiktiv</span>}
              </div>
              <h1 id="expose-titel" className="ov-h1 ov-hero-in mt-5 text-balance text-ink-900" style={{ "--ov-delay": "100ms" }}>{p.titel}</h1>
              <p className="ov-hero-in mt-4 flex items-center gap-2 text-[15px] font-medium text-ink-600" style={{ "--ov-delay": "140ms" }}>
                <MapPin aria-hidden="true" className="h-4 w-4 shrink-0 text-ov-600" />
                {[p.region, p.bundesland, LAENDER[p.land]].filter(Boolean).join(" · ")}
              </p>
              <p className="ov-lead ov-hero-in mt-5 max-w-2xl whitespace-pre-line text-pretty text-ink-600" style={{ "--ov-delay": "180ms" }}>{p.beschreibung}</p>
              {p.highlights?.length > 0 && (
                <ul className="ov-hero-in mt-6 grid gap-2.5 sm:grid-cols-2" style={{ "--ov-delay": "220ms" }}>
                  {p.highlights.map((h) => (
                    <li key={h} className="flex items-start gap-2.5 text-[15px] text-ink-700">
                      <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-ov-500 text-white"><Check aria-hidden="true" className="h-3 w-3" strokeWidth={3} /></span>
                      {h}
                    </li>
                  ))}
                </ul>
              )}
              <div className="ov-hero-in mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap" style={{ "--ov-delay": "260ms" }}>
                <Button href={hauptAktion.href} size="lg" pfeil className="w-full sm:w-auto">{hauptAktion.label}</Button>
                {!nutzer && <Button href={`/login?weiter=${encodeURIComponent(portalLink)}`} size="lg" variant="secondary" className="w-full sm:w-auto">Ich habe ein Konto</Button>}
              </div>
              <p className="ov-hero-in mt-4 flex items-start gap-2 text-[14px] text-ink-600" style={{ "--ov-delay": "300ms" }}>
                <FileDown aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" />
                <span>
                  <a href={`/api/boerse/${p.slug}/teaser`} target="_blank" rel="noopener" className="font-semibold text-ov-700 underline decoration-ov-300 underline-offset-4 hover:text-ov-800">
                    Teaser als PDF
                  </a>{" "}
                  – öffentliche Eckdaten zum Weitergeben, ohne vertrauliche Angaben.
                </span>
              </p>
            </div>

            <div className="ov-hero-in min-w-0" style={{ "--ov-delay": "200ms" }}>
              <div className="overflow-hidden rounded-[2rem] bg-white shadow-e4 ring-1 ring-ink-200/70">
                <div className="relative">
                  <TypIllustration typ={p.typ} variante={varianteAus(p.id || p.slug)} className="h-36 w-full sm:h-44" />
                  <span className="absolute left-4 top-4 rounded-full bg-white/95 px-2.5 py-1 text-[11.5px] font-semibold text-ink-700 shadow-sm ring-1 ring-ink-200/70">Exposé · öffentliche Eckdaten</span>
                </div>
                <dl className="grid grid-cols-2 border-b border-ink-100">
                  <div className="min-w-0 px-5 py-5 md:px-6">
                    <dt className="text-[12px] font-medium text-ink-500">Leistung</dt>
                    <dd className="ov-num mt-1 font-display text-[28px] font-extrabold leading-none tracking-tight text-ink-900 md:text-[32px]">{leistungGross}</dd>
                    {leistungZusatz && <dd className="mt-1.5 text-[12.5px] font-medium text-ink-500">{leistungZusatz}</dd>}
                  </div>
                  <div className="min-w-0 border-l border-ink-100 px-5 py-5 md:px-6">
                    <dt className="text-[12px] font-medium text-ink-500">Preisindikation</dt>
